#!/usr/bin/env python3
import json

def a(href, text):
    return '<a href="%s" target="_blank" rel="noopener">%s</a>' % (href, text)
def p(html): return {'t': 'p', 'html': html}

NYER = 'https://www.newyorker.com/magazine/2023/12/04/how-jensen-huangs-nvidia-is-powering-the-ai-revolution'
DENNY = 'https://blogs.nvidia.com/blog/nvidia-dennys-trillion/'
TIMELINE = 'https://www.nvidia.com/en-us/about-nvidia/corporate-timeline/'
INC = 'https://www.inc.com/ben-sherry/nvidia-founder-jensen-huang-on-how-a-close-call-with-failure-helps-him-dominate-ai.html'
TT = 'https://www.taipeitimes.com/News/taiwan/archives/2025/02/09/2003831587'
NVREL = 'https://nvidianews.nvidia.com/news/nvidia-announces-ceo-transition'
WSJ = 'https://www.tovima.com/wsj/nvidia-ceo-jensen-huang-resigns/'
AXIOS = 'https://www.axios.com/2026/11/12/nvidia-jensen-huang-out'
BTUS = 'https://www.businesstimes.com.sg/companies-markets/capital-markets-currencies/us-stocks-equities-close-lower-nvidia-drop-outweighs-energy-gains'
ETVANDA = 'https://m.economictimes.com/markets/us-stocks/news/us-stocks-retail-buyers-limit-nvidia-stock-rout/amp_articleshow/135782108.cms'
YFIN = 'https://finance.yahoo.com/quote/NVDA/history/'

lr = {
 'title': 'The booth that built the boom',
 'fact': "A Slow Burn long read, Friday 13 November 2026. On Thursday, Jensen Huang resigned from the company he founded in a Denny's booth thirty-three years ago - effective immediately, no reason given, the finance chief holding the chair. The man who left had taken Nvidia from a quadrilateral bet that nearly bankrupted it to the GPU, to CUDA, to the silicon the AI age runs on. This is the build story: Taiwan, Kentucky, Oregon, a million chips in four months, a software wager nobody asked for, and the single-sentence ending that moved the entire market by 4.34%.",
 'groups': []
}
G = lr['groups']

G.append({'heading': '1. The dishwasher', 'blocks': [
 p(' The origin story Jensen Huang tells about himself does not start with a chip. It starts with dirty plates. Born in Taiwan in 1963, he was sent to America at nine - an unaccompanied minor, with his older brother - to an uncle in Tacoma, and then to the Oneida Baptist Institute in Kentucky, which the uncle believed was a prestigious boarding school. It was a religious reform academy. Huang\'s roommate was seventeen and illiterate; the boy showed the nine-year-old his knife-fight scars on the first night. Huang taught him to read; the roommate taught him to bench-press. "I ended up doing a hundred pushups every night before bed," Huang told ' + a(NYER, 'Stephen Witt\'s New Yorker profile') + '. At the public school nearby, the undersized immigrant with accented English was, a classmate recalls, "a perfect target" - bullied daily, once nearly shaken off the rickety footbridge over the river on the walk to school. By the end of the year he was leading those same boys into the woods. "Back then, you just had to toughen up and move on." In 2019 he donated a building to the school.'),
 p(' The family reunited in Oregon, and the toughness found its instruments: Huang skipped two grades, was nationally ranked at table tennis, and graduated at sixteen. At Oregon State he studied electrical engineering and won his lab partner, Lori Mills, by out-homeworking two hundred and fifty rivals - "not with my looks, of course, but with my strong capability to complete homework." They married; they both designed chips in Silicon Valley; she made more than he did. And somewhere in there, at fifteen, he had worked the floor of a Denny\'s in Portland: "I was a dishwasher, I was a busboy, I waited tables," he told the diner chain\'s chief executive decades later. "No one can carry more coffee cups than I can" (' + a(DENNY, 'Nvidia\'s own telling') + '). The lesson he says the rush hour taught him became his management philosophy: "I find that I think best when I\'m under adversity. My heart rate actually goes down."'),
]})

G.append({'heading': '2. The booth', 'blocks': [
 p(' In 1993, three friends met at a Denny\'s in San Jose to talk about a chip. Chris Malachowsky and Curtis Priem were veteran microchip designers; Huang, at thirty, was younger than both - and both thought he should be chief executive. "He was a fast learner," Malachowsky said. The booth was chosen with an engineer\'s logic: quieter than a house with children, bottomless coffee, and, as Huang put it, "no one could chase you out." Their idea: a chip to give personal computers realistic three-dimensional graphics, just as artists were learning to build worlds out of polygons. The company was incorporated on 5 April 1993 (' + a(TIMELINE, 'the company\'s own timeline') + '). They wanted a name that would leave competitors, in Priem\'s words, "green with envy" - first NVision, until that turned out to belong to a toilet-paper manufacturer, then Nvidia, from the Latin invidia. Envy.'),
 p(' What the booth produced was not a business plan so much as a temperament. Huang drafted the paperwork at that Denny\'s and then ran the company, without interruption, for thirty-three years (' + a(NYER, 'the New Yorker') + '). Decades later, when the diner chain gave him a plaque at the same restaurant, he ordered a Lumberjack Slam, a Moons Over My Hammy and a Super Bird, tipped the waitress a thousand dollars, and advised young people to start their careers in restaurants: "It teaches you humility, it teaches you hard work, it teaches you hospitality" (' + a(DENNY, 'Nvidia\'s blog') + '). The booth is a cute story now. It was, at the time, the entire head office of a company with no revenue, three founders, and a thesis about triangles.'),
]})

G.append({'heading': '3. The mistake', 'blocks': [
 p(' The thesis was wrong. Where every competitor built graphics from triangles, Nvidia\'s founders chose quadrilaterals - and soon after Nvidia\'s first product shipped, Microsoft announced its graphics software would support only triangles. The company had designed itself out of the market with its first chip (' + a(NYER, 'the New Yorker') + '). Huang\'s answer became the company\'s founding legend. In 1996 he laid off more than half of Nvidia\'s hundred employees and bet the remaining money on a production run of an untested chip built the conventional, triangular way. By the time the chip - the RIVA 128 - shipped, Nvidia had enough cash to keep the lights on for about one more month. It sold over a million units in four months (' + a(INC, 'Inc.') + ').'),
 p(' The scar became the operating system. "Our company is 30 days from going out of business" stayed an unofficial Nvidia motto for three decades; Huang told the 2023 DealBook summit, after a quarter in which revenue had grown 206% to $18.1 billion, that he still woke every morning "in some condition of concern" (' + a(INC, 'Inc.') + '). His biographer calls the condition a hatred of losing: an absolute workaholic, forty years of long days, who schedules by "the speed of light" - work out how fast a task could conceivably be done, then work backward to something merely very fast (' + a(TT, 'the Taipei Times on Stephen Witt\'s biography') + '). The quadrilateral failure taught the booth its rule: the company that nearly dies once organises itself so it can never be surprised again. The rule held for three decades. What finally ended the run was not a technology bet at all.'),
]})

G.append({'heading': '4. The bet nobody asked for', 'blocks': [
 p(' The RIVA saved the company; the GPU named it. In 1999 Nvidia shipped the GeForce 256 and called it the world\'s first graphics processing unit - a chip that took the geometry work off the main processor (' + a(TIMELINE, 'the company timeline') + '). Gaming paid for it all. Then Huang made the wager that defines the company: in 2006 he began pushing the GPU beyond graphics, and in 2007 Nvidia unveiled CUDA - a way for scientists and engineers to write ordinary software for a graphics chip (' + a(TIMELINE, 'the timeline') + '). Wall Street did not ask for it, customers were in no hurry, and the profit margins of a games business did not obviously want a science project attached. Huang built it anyway, year after expensive year: a parallel-computing platform with no mass market yet, kept alive by a monopolist\'s patience.'),
 p(' "He is a patient monopolist," Witt wrote, in the phrase that frames the whole build (' + a(NYER, 'the New Yorker') + '). By 2013, on the strength of academic results, Huang bet the company\'s future squarely on artificial intelligence - a field that had disappointed investors for decades. Even his own lead deep-learning researcher, Bryan Catanzaro, doubted: "I didn\'t want him to fall into the same trap that the A.I. industry has had in the past. But, ten years plus down the road, he was right." The CUDA bet is the part of the Nvidia story every founder should memorise, because it was not vision in the cinematic sense. It was plumbing laid for years at real cost, against scepticism, on the reasoning that if the world ever needed parallel computing at scale, the world would have exactly one supplier. Huang\'s own summary is drier: "I do everything I can not to go out of business. I do everything I can not to fail."'),
]})

G.append({'heading': '5. The earthquake', 'blocks': [
 p(' The world\'s need arrived in two shocks, a decade apart. First, in 2012, the AlexNet neural network - trained on Nvidia GPUs - shattered the image-recognition record and lit the modern AI era; Nvidia\'s own timeline lists it as the company\'s third great milestone (' + a(TIMELINE, 'the timeline') + '). Then, in late 2022, ChatGPT - trained on an Nvidia supercomputer - turned the era into a gold rush. When the market grasped it, on 25 May 2023, Nvidia\'s value rose about two hundred billion dollars in a single session, one of the largest one-day gains in stock-market history; by the close it was the sixth most valuable company on earth, worth more than Walmart and ExxonMobil combined (' + a(NYER, 'the New Yorker') + ').'),
 p(' The metaphors queued up. Huang was Samuel Brannan, the merchant who sold picks to the forty-niners. "There\'s a war going on out there in A.I., and Nvidia is the only arms dealer," one Wall Street analyst told the New Yorker. More than four million developers now build on its platform; more than forty thousand companies use its AI technology (' + a(TIMELINE, 'the company\'s count') + '). The dishwasher from the Portland Denny\'s had become, in the Journal\'s words, the face of the AI arms race - mobbed in Taipei night markets, a fixture at the White House, worth more than forty billion dollars on his own stock (' + a(WSJ, 'the Journal') + '; ' + a(NYER, 'the New Yorker') + '). And the whole edifice - the customers, the export licences, the trillion-dollar supply chain - rested, as Thursday would prove, on one man\'s continued presence in the chair.'),
]})

G.append({'heading': '6. The summit, and its price', 'blocks': [
 p(' At the summit, Nvidia stopped being a company and became terrain. Its chips were the contested ground of American-Chinese policy: Washington restricted what could be sold to China; Huang argued, lobbied and charmed, and President Trump - who called him an "amazing guy" and an "honorable man" this very week - approved shipments despite the security establishment\'s objections (' + a(WSJ, 'the Journal') + '). The arrangement made Huang the most geopolitically exposed chief executive in the world. It also made his personal conduct a matter of state. The Journal and the New York Times have reported the sequence: an American investigation touching a customer\'s executive close to Huang; Nvidia\'s board hiring outside counsel to investigate; a letter to staff on Sunday; a board meeting; then Thursday. Nvidia has given no reason for the resignation, and this piece keeps that framing (' + a(NVREL, 'the company\'s release') + '; ' + a(WSJ, 'the Journal\'s reporting') + ').'),
 p(' The structural warning had been sitting in Nvidia\'s own paperwork the whole time. Its proxy statement cautions that the company is "highly dependent on the services of our longstanding executive team," and that weak succession planning could "hinder our strategic planning, execution, and long-term success." Huang ran Nvidia with roughly sixty direct reports and a professed disbelief in succession planning - leaders should pass on knowledge continuously, he said, not in a handover (' + a(WSJ, 'the Journal') + '). It is the quadrilateral lesson inverted: the man who organised a company never to be surprised by a technology left it exposed to the oldest risk in business, the one every founder swears they are exempt from.'),
]})

G.append({'heading': '7. The Thursday', 'blocks': [
 p(' The ending took one sentence. "Jensen Huang has resigned as President, Chief Executive Officer, and a member of the Board, effective immediately" (' + a(NVREL, 'the release') + '). No reason. Colette Kress - the finance chief since 2013, twenty-five years at Cisco and Microsoft before that - agreed to serve as interim CEO while keeping her own job; Harvey Jones, a venture investor and former Synopsys chief, became the first chair the board has ever had; the search is internal and external; the 17 November earnings date did not move. Kress wrote to the staff: "I believe deeply in this company and in its future... let\'s move forward together, with the same determination and commitment that have always defined this company" (' + a(AXIOS, 'Axios') + '). The board\'s own goodbye was one clause long: "Jensen\'s contributions to NVIDIA are profound."'),
 p(' The market held a referendum and could not make up its mind. The stock fell out of bed at the open - a double-digit percentage loss in the first minutes - and then the buyers came: retail investors put a net $111 million into Nvidia in the first half-hour, the biggest opening bid Vanda Analytics has ever recorded (' + a(ETVANDA, 'the wire') + '). The close was $166.19, down 4.34% (' + a(YFIN, 'the official table') + '). Nvidia\'s rivals rose - AMD and Broadcom more than 5% each - while the companies that rent its future, the neoclouds, sank with it (' + a(BTUS, 'Reuters') + '). Thirty-three years from the booth to the exit, and the final trading day of the founder was also a verdict on the build: the machine he made was bigger than him by exactly the morning\'s recovery. Tonight the booth is just a booth again - a plaque in a Denny\'s in San Jose where three engineers once drank bottomless coffee. The company runs on, thirty days from going out of business, as always. That was always the point.'),
]})


